const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);let W=1000,H=600,DPR=1;
function resize(){const r=canvas.getBoundingClientRect();DPR=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*DPR);canvas.height=Math.round(r.height*DPR);W=r.width;H=r.height;ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
const keys={};let state='menu',last=0,time=90,player,ball,rival,keeper,score=0,opponent=0,gateY=.5,gateDir=1,gateSpeed=.28,meter=0,charging=false,toastTimer=0,particles=[],decor=[],soundOn=true,audio;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a);
function newMatch(){score=0;opponent=0;time=90;meter=12;player={x:.17,y:.52,vx:0,vy:0,r:.025,faceX:1,faceY:0};ball={x:.205,y:.52,vx:0,vy:0,r:.012,owner:'you',spin:0};rival={x:.57,y:.5,vx:0,vy:0};keeper={x:.91,y:.5};particles=[];gateY=.5;state='playing';$('score').textContent='00';$('rival').textContent='00';$('overlay').classList.add('hidden');last=performance.now();toast('TIDE IS TURNING — FIND THE OPENING');}
function showOverlay(mode){state=mode;$('overlay').classList.remove('hidden');if(mode==='pause'){$('eyebrow').textContent='TIME IS ON HOLD';$('title').innerHTML='TAKE A<br><em>BREATHER</em>';$('desc').textContent='The storm can wait. Your rival probably will not.';$('rules').style.display='none';$('start').textContent='RESUME MATCH';$('hint').textContent='PRESS P OR ESC TO RETURN TO THE PITCH'}else if(mode==='end'){$('eyebrow').textContent=score>=3?'BREAKWATER CHAMPION':'FINAL WHISTLE';$('title').innerHTML=score>=3?'THE TIDE<br><em>IS YOURS</em>':'NOT THIS<br><em>TIME</em>';$('desc').textContent=`Final score ${score} – ${opponent}. ${score>=3?'You mastered the moving Storm Gate. The coast is yours.':'The gate got away this time. Take another run at the Breakwater.'}`;$('rules').style.display='none';$('start').textContent='PLAY AGAIN';$('hint').textContent='90 SECONDS · THREE GOALS TO WIN'}else{$('eyebrow').textContent='A NEW COASTAL CIRCUIT';$('title').innerHTML='TIDE<br><em>BREAK</em>';$('desc').textContent='The storm has split the goal into moving gates. Read the current, outplay the keeper, and make the Breakwater your pitch.';$('rules').style.display='grid';$('start').textContent='KICK OFF';$('hint').textContent='NO REFEREE. NO RESETS. JUST THE LAST SHOT.'}}
$('start').onclick=()=>state==='pause'?(state='playing',$('overlay').classList.add('hidden'),last=performance.now()):newMatch();$('pause').onclick=()=>state==='playing'?showOverlay('pause'):state==='pause'?($('overlay').classList.add('hidden'),state='playing',last=performance.now()):null;
$('sound').onclick=()=>{soundOn=!soundOn;$('sound').textContent=soundOn?'♫':'♪';if(soundOn)beep(440,.05)};
function beep(freq=300,dur=.08){if(!soundOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=freq;g.gain.value=.045;g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.start();o.stop(audio.currentTime+dur)}catch(e){}}
function toast(s){const t=$('toast');t.textContent=s;t.classList.add('show');toastTimer=1.5}
function keyName(k){return k===' '||k==='Spacebar'?'shoot':({ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',e:'tide',E:'tide',Shift:'tide', ' ':'shoot'}[k]||k)}
addEventListener('keydown',e=>{let k=keyName(e.key);if(['up','down','left','right','shoot','tide'].includes(k))e.preventDefault();if(k==='p'||k==='Escape'){if(state==='playing')showOverlay('pause');else if(state==='pause'){$('overlay').classList.add('hidden');state='playing';last=performance.now()}return}if(k==='shoot'&&!keys.shoot)shoot();keys[k]=true});addEventListener('keyup',e=>{let k=keyName(e.key);keys[k]=false});
document.querySelectorAll('[data-key]').forEach(b=>{let k=b.dataset.key;for(const ev of ['pointerdown','pointerup','pointercancel','pointerleave'])b.addEventListener(ev,e=>{e.preventDefault();if(ev==='pointerdown'){b.setPointerCapture?.(e.pointerId);if(k==='shoot')shoot();keys[k]=true}else keys[k]=false})});
function shoot(){if(state!=='playing'||ball.owner!=='you')return;let p=player;let dx=p.faceX||1,dy=p.faceY;let power=4.8+meter*.055+(keys.tide?2.3:0);ball.owner=null;ball.x=p.x+dx*.045;ball.y=p.y+dy*.045;ball.vx=dx*power;ball.vy=dy*power+(keys.tide?-.25:0);ball.spin=keys.tide?Math.sign(dy||1)*1.3:0;if(keys.tide){meter=Math.max(0,meter-32);toast('TIDE DRIVE!');beep(760,.16)}else beep(430,.08);particles.push({x:ball.x,y:ball.y,n:keys.tide?20:8,c:keys.tide?'#70fff1':'#ffd47d',life:.4})}
function resetAfterGoal(who){if(who==='you'){score++;$('score').textContent=String(score).padStart(2,'0');meter=Math.min(100,meter+28);toast(score>=3?'CHALLENGE CLEARED!':'GOAL! — THE GATE SHIFTS');beep(720,.28)}else{opponent++;$('rival').textContent=String(opponent).padStart(2,'0');toast('RIVAL GOAL — DEFEND THE BREAKWATER');beep(180,.2)}if(score>=3||time<=0){setTimeout(()=>showOverlay('end'),900);return}player.x=.17;player.y=.5;player.vx=player.vy=0;rival.x=.57;rival.y=.5;ball.x=.205;ball.y=.5;ball.vx=ball.vy=0;ball.owner='you';}
function update(dt){time-=dt;if(time<=0){time=0;showOverlay('end');return}gateY+=gateDir*gateSpeed*dt;if(gateY<.28||gateY>.72)gateDir*=-1;keeper.y+=(gateY-keeper.y)*Math.min(1,dt*2.7);let ax=(keys.right?1:0)-(keys.left?1:0),ay=(keys.down?1:0)-(keys.up?1:0),len=Math.hypot(ax,ay)||1;ax/=len;ay/=len;let speed=.39;player.vx+=(ax*speed-player.vx)*Math.min(1,dt*8);player.vy+=(ay*speed-player.vy)*Math.min(1,dt*8);player.x=clamp(player.x+player.vx*dt,.07,.87);player.y=clamp(player.y+player.vy*dt,.12,.88);if(Math.hypot(ax,ay)>.1){player.faceX=ax;player.faceY=ay}
let dx=ball.x-player.x,dy=ball.y-player.y,dist=Math.hypot(dx,dy);if(ball.owner==='you'){ball.x=player.x+player.faceX*.043;ball.y=player.y+player.faceY*.043;if(dist>.09)meter=Math.min(100,meter+dt*5.2)}else if(ball.owner==='rival') {ball.x=rival.x-.034;ball.y=rival.y;}
let rd=Math.hypot(ball.x-rival.x,ball.y-rival.y);if(ball.owner!=='you'){let tx=ball.x-.027,ty=ball.y;let rx=tx-rival.x,ry=ty-rival.y,rl=Math.hypot(rx,ry)||1;rival.x=clamp(rival.x+rx/rl*.25*dt,.12,.89);rival.y=clamp(rival.y+ry/rl*.25*dt,.12,.88);if(rd<.045&&ball.owner!=='rival'&&ball.vx<.65){ball.owner='rival';ball.vx=ball.vy=0}}else{let tx=player.x-.085,ty=player.y+.035,rx=tx-rival.x,ry=ty-rival.y,rl=Math.hypot(rx,ry)||1;rival.x=clamp(rival.x+rx/rl*.14*dt,.22,.89);rival.y=clamp(rival.y+ry/rl*.14*dt,.12,.88)}
if(ball.owner==='rival'&&ball.x>.76){ball.owner=null;ball.vx=3.4;ball.vy=(.5-ball.y)*1.3;}
if(!ball.owner){if(ball.spin){ball.vy+=ball.spin*dt;ball.spin*=Math.exp(-dt*1.6)}ball.x+=ball.vx*dt;ball.y+=ball.vy*dt;ball.vx*=Math.exp(-dt*.72);ball.vy*=Math.exp(-dt*.72);if(ball.y<.09||ball.y>.91){ball.y=clamp(ball.y,.09,.91);ball.vy*=-.72}if(ball.x<.065){ball.x=.065;ball.vx*=-.7}let mouth=Math.abs(ball.y-.5)<.145,gate=Math.abs(ball.y-gateY)<.09;if(ball.x>.95&&mouth&&gate){resetAfterGoal('you');return}if(ball.x>.96&&mouth&&!gate&&ball.vx>0){ball.x=.945;ball.vx=-Math.abs(ball.vx)*.6;ball.vy+=(ball.y>gateY?1:-1)*.7;toast('GATE CLOSED!');}if(ball.x>.96&&Math.abs(ball.y-.5)>.15&&ball.vx>0){ball.x=.94;ball.vx=-Math.abs(ball.vx)*.6}if(ball.x<.045&&Math.abs(ball.y-.5)<.14&&ball.vx<0){resetAfterGoal('rival');return}if(ball.x<.04){ball.x=.05;ball.vx=Math.abs(ball.vx)*.6}if(Math.hypot(ball.x-player.x,ball.y-player.y)<.045&&ball.vx<1.6&&ball.x<.79)ball.owner='you';if(Math.hypot(ball.x-rival.x,ball.y-rival.y)<.043&&ball.vx<1.5&&ball.owner===null)ball.owner='rival'}
if(ball.owner==='rival'&&ball.x<.1&&Math.abs(ball.y-.5)<.14){resetAfterGoal('rival');return}if(ball.owner==='rival'&&Math.hypot(ball.x-player.x,ball.y-player.y)<.05){ball.owner='you';toast('TACKLE!');beep(320,.05)}
$('clock').textContent=String(Math.ceil(time)).padStart(2,'0');$('clock').classList.toggle('danger',time<15);$('meter').style.width=meter+'%';if(toastTimer>0&&(toastTimer-=dt)<=0)$('toast').classList.remove('show');for(let p of particles)p.life-=dt;particles=particles.filter(p=>p.life>0);}

function path(points){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x*W,y*H):ctx.moveTo(x*W,y*H));ctx.closePath()}
function draw(){ctx.clearRect(0,0,W,H);let bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#164351');bg.addColorStop(.5,'#153c49');bg.addColorStop(1,'#0b2b3d');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
// distant sea and storm
ctx.fillStyle='#061d2b';ctx.fillRect(0,0,W,H*.115);ctx.fillStyle='#267082';ctx.globalAlpha=.3;for(let i=0;i<20;i++){let x=((i*103+performance.now()*.012)%W);ctx.fillRect(x,H*.045+Math.sin(i+performance.now()*.001)*5,50,2)}ctx.globalAlpha=1;
// pitch
let l=W*.065,r=W*.95,t=H*.105,b=H*.9;ctx.fillStyle='#154c50';ctx.fillRect(l,t,r-l,b-t);for(let i=0;i<8;i++){ctx.fillStyle=i%2?'#1a5856':'#1b6058';ctx.fillRect(l+(r-l)*i/8,t,(r-l)/8,b-t)}ctx.strokeStyle='#a5e8d677';ctx.lineWidth=1.5;ctx.strokeRect(l,t,r-l,b-t);ctx.beginPath();ctx.moveTo(W*.5,t);ctx.lineTo(W*.5,b);ctx.stroke();ctx.beginPath();ctx.ellipse(W*.5,H*.502,W*.105,H*.17,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#cfffff91';ctx.beginPath();ctx.arc(W*.5,H*.5,3,0,Math.PI*2);ctx.fill();
// penalty boxes and goal area
ctx.strokeRect(l,t+(b-t)*.28,(r-l)*.14,(b-t)*.44);ctx.strokeRect(r-(r-l)*.14,t+(b-t)*.28,(r-l)*.14,(b-t)*.44);ctx.strokeRect(l,t+(b-t)*.38,(r-l)*.055,(b-t)*.24);ctx.strokeRect(r-(r-l)*.055,t+(b-t)*.38,(r-l)*.055,(b-t)*.24);
// perimeter seawalls
ctx.fillStyle='#102d3a';ctx.fillRect(l-4,t-7,r-l+8,7);ctx.fillRect(l-4,b,r-l+8,7);for(let i=0;i<24;i++){let x=l+i*(r-l)/24;ctx.fillStyle=i%2?'#4ed5d0':'#75e7d8';ctx.globalAlpha=.3;ctx.fillRect(x,t-6,16,2);ctx.fillRect(x,b+3,16,2)}ctx.globalAlpha=1;
// moving storm gate over goal mouth
let gy=gateY*H;ctx.save();ctx.shadowBlur=15;ctx.shadowColor='#65fff0';ctx.fillStyle='#55f1e4';ctx.fillRect(r-3,t+(b-t)*.5-H*.145,7,H*.5-H*.145);ctx.fillRect(r-3,gy-H*.085,12,H*.17);ctx.restore();ctx.strokeStyle='#e3fffc';ctx.lineWidth=4;ctx.strokeRect(r-8,H*.5-H*.145,16,H*.29);ctx.fillStyle='#d3ffff';ctx.font=`${Math.max(9,W*.013)}px system-ui`;ctx.textAlign='center';ctx.fillText('STORM GATE',r-22,t+H*.5-H*.16);
// goals and water decorations
ctx.fillStyle='#092634';ctx.fillRect(l-10,H*.5-H*.12,10,H*.24);ctx.fillRect(r,H*.5-H*.12,10,H*.24);ctx.strokeStyle='#c9f8ff66';ctx.lineWidth=1;for(let y=-.1;y<=.1;y+=.04){ctx.beginPath();ctx.moveTo(r,H*(.5+y));ctx.lineTo(r+10,H*(.5+y));ctx.stroke()}
// floating salt spray flecks
for(let i=0;i<18;i++){let x=(i*127+performance.now()*.006*(i%2?1:-1))%W,y=H*(.15+(i*37%70)/100);ctx.fillStyle='#d6fffc';ctx.globalAlpha=.18;ctx.fillRect(x,y,2,2)}ctx.globalAlpha=1;
// keeper
playerDraw(keeper.x,keeper.y,'#ffb85b','KEEPER',.022);playerDraw(rival.x,rival.y,'#ff6e78','RIVAL',.024);playerDraw(player.x,player.y,'#52f0dd','YOU',.025);
// ball
let bx=ball.x*W,by=ball.y*H,br=Math.max(5,W*.011);ctx.save();ctx.shadowColor='#fff';ctx.shadowBlur=ball.spin?18:8;ctx.fillStyle='#f9ffff';ctx.beginPath();ctx.arc(bx,by,br,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#40777a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(bx-br*.7,by-br*.5);ctx.lineTo(bx+br*.7,by+br*.5);ctx.moveTo(bx+br*.6,by-br*.6);ctx.lineTo(bx-br*.5,by+br*.65);ctx.stroke();ctx.restore();
for(const p of particles){ctx.globalAlpha=clamp(p.life/.4,0,1);ctx.fillStyle=p.c;for(let i=0;i<p.n;i++){let a=i*2.4+p.life*8,rr=(.4-p.life)*W*.2+Math.sin(i*2)*4;ctx.beginPath();ctx.arc(p.x*W+Math.cos(a)*rr,p.y*H+Math.sin(a)*rr,rand(1,3),0,Math.PI*2);ctx.fill()}}ctx.globalAlpha=1;
// tide charge feedback
if(keys.tide&&ball.owner==='you'){ctx.strokeStyle='#86fff0';ctx.lineWidth=2;ctx.globalAlpha=.55+.3*Math.sin(performance.now()*.02);ctx.beginPath();ctx.arc(player.x*W,player.y*H,player.r*W*(1.8+meter/85),0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
}
function playerDraw(x,y,color,label,radius){const px=x*W,py=y*H,r=radius*W;ctx.save();ctx.fillStyle='#00192388';ctx.beginPath();ctx.ellipse(px+2,py+r*.72,r*1.1,r*.48,0,0,Math.PI*2);ctx.fill();ctx.shadowColor=color;ctx.shadowBlur=12;ctx.fillStyle=color;ctx.beginPath();ctx.arc(px,py,r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#eaffff';ctx.beginPath();ctx.arc(px,py-r*.1,r*.36,0,Math.PI*2);ctx.fill();ctx.fillStyle='#031d2c';ctx.font=`900 ${Math.max(8,W*.011)}px system-ui`;ctx.textAlign='center';ctx.fillText(label,px,py+r+13);ctx.restore()}
function frame(ts){let dt=Math.min(.05,(ts-last)/1000||0);last=ts;if(state==='playing')update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
</script></body></html>
